import hashlib, json, os, sys

def sha(p):
    return hashlib.sha256(open(p, 'rb').read()).hexdigest()

pins = json.load(open('benchmark/writing/input-pins.json'))
print('input-pins top keys', list(pins))
prot = pins.get('protected_inputs_sha256', {})
bad = 0
for k, v in prot.items():
    h = v if isinstance(v, str) else v.get('sha256')
    if not os.path.exists(k):
        print('MISSING', k); bad += 1
    elif sha(k) != h:
        print('DRIFT', k); bad += 1
print('protected entries', len(prot), 'bad', bad)
for name in ['benchmark/writing/verify_method.py', 'benchmark/writing/README.md', 'benchmark/writing/method.json',
             'benchmark/writing/baseline-addendum.json', 'benchmark/writing/build_addendum.py',
             'benchmark/writing/current-pins.json', 'benchmark/protocol.md', 'benchmark/writing/input-pins.json',
             'benchmark/preparation.json', 'benchmark/writing/controls.json']:
    print(name, sha(name), name in prot)
cp = json.load(open('benchmark/writing/current-pins.json'))
cbad = 0
for sec in ('current', 'frozen'):
    for k, v in cp[sec].items():
        if sha(k) != v['sha256'] or os.path.getsize(k) != v['size']:
            print('CP DRIFT', k); cbad += 1
print('current-pins bad', cbad)
for root, dirs, files in os.walk('benchmark'):
    if '__pycache__' in dirs:
        print('PYCACHE', root)
